def get_component_min_max_row(grid, position, rows7=7):
    """Get min and max row in 4-connected component starting at position"""
    rows = rows7
    cols = 7
    visited = set()
    queue = deque([position])
    visited.add(position)
    min_r = rows
    max_r = -1
    while queue:
        cr, cc = queue.popleft()
        if cr < min_r:
            min_r = cr
        if cr > max_r:
            max_r = cr
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return min_r, max_r

