def get_runs(graph):
    """Get horizontal runs per row"""
    runs = []
    for r in range(len(graph)):
        run_list = []  # [(start_col, end_col, length), ...]
        c = 0
        while c < len(graph[r]):
            if graph[r][c] == 8:
                start = c
                while c < len(graph[r]) and graph[r][c] == 8:
                    c += 1
                end = c - 1
                run_list.append((start, end, end - start + 1))
            else:
                c += 1
        runs.append(run_list)
    return runs

def get_v_runs(graph):
    """Get vertical runs per column"""
    runs = []
    for c in range(len(graph[0])):
        run_list = []  # [(start_row, end_row, length), ...]
        r = 0
        while r < len(graph):
            if graph[r][c] == 8:
                start = r
                while r < len(graph) and graph[r][c] == 8:
                    r += 1
                end = r - 1
                run_list.append((start, end, end - start + 1))
            else:
                r += 1
        runs.append(run_list)
    return runs

