    cols = [j for i, row in enumerate(grid) for j, val in enumerate(row) if val == 8]
    return (min(rows), max(rows), min(cols), max(cols))

def quadrant_prediction(r, c, grid):
    bbox = find_bbox_8s(grid)
    min_r, max_r, min_c, max_c = bbox

    mid_r = (min_r + max_r) / 2
    mid_c = (min_c + max_c) / 2

    in_top = r < mid_r
    in_bottom = r >= mid_r
    in_left = c < mid_c
    in_right = c >= mid_c

    if in_top and in_left:
        return 1
    elif in_top and in_right:
        return 4
    elif in_bottom and in_left:
        return 3
    elif in_bottom and in_right:
        return 2
    else:
        return 0

